/**
 * Regeln für src/app/robots.js (MetadataRoute.Robots).
 *
 * Such- und Abrufcrawler (Googlebot, Bingbot, OAI-SearchBot, ChatGPT-User,
 * PerplexityBot, Claude-SearchBot, Claude-User …) fallen unter "*" und sind
